import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:image_picker/image_picker.dart';
import 'core/providers/gemini_client.dart';
void main()=>runApp(const AiOsApp());
const secureStorage=FlutterSecureStorage();
class AiOsApp extends StatelessWidget{const AiOsApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'AI OS',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:const MainShell());}
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}
class _MainShellState extends State<MainShell>{int index=0;@override Widget build(BuildContext c){final p=[const ChatPage(),const AiRoomPage(),const HistoryPage(),const SettingsPage()];return Scaffold(body:SafeArea(child:IndexedStack(index:index,children:p)),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'채팅'),NavigationDestination(icon:Icon(Icons.hub_outlined),label:'AI 대화방'),NavigationDestination(icon:Icon(Icons.history),label:'기록'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'설정')]));}}
class ChatMessage{ChatMessage(this.text,this.user,{this.attachment});final String text;final bool user;final String? attachment;}
class ChatPage extends StatefulWidget{const ChatPage({super.key});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final controller=TextEditingController();final messages=<ChatMessage>[];final gemini=const GeminiClient();bool busy=false;String? attachment;
Future<void> attach()async{await showModalBottomSheet<void>(context:context,builder:(ctx)=>SafeArea(child:Wrap(children:[ListTile(leading:const Icon(Icons.camera_alt_outlined),title:const Text('카메라 촬영'),onTap:()async{Navigator.pop(ctx);final x=await ImagePicker().pickImage(source:ImageSource.camera,imageQuality:90);if(x!=null&&mounted)setState(()=>attachment=x.path);}),ListTile(leading:const Icon(Icons.photo_library_outlined),title:const Text('사진 선택'),onTap:()async{Navigator.pop(ctx);final x=await ImagePicker().pickImage(source:ImageSource.gallery);if(x!=null&&mounted)setState(()=>attachment=x.path);}),ListTile(leading:const Icon(Icons.folder_open),title:const Text('파일 첨부'),subtitle:const Text('문서 선택기는 다음 버전에서 네이티브 방식으로 연결'),onTap:()=>Navigator.pop(ctx))])));}
String localFallback(String q){final s=q.toLowerCase();if(s.contains('ai os')||s.contains('기능'))return 'AI OS는 여러 AI를 하나의 채팅 인터페이스에서 선택·조합하는 Multi-Agent AI 운영체제입니다. 현재 연결된 API가 없어서 온디바이스 기본 응답 모드로 답변하고 있습니다. 설정에서 무료 또는 유료 Provider를 연결하면 AI Router가 사용 가능한 AI를 우선순위에 따라 선택합니다.';return '현재 외부 AI Provider가 연결되지 않아 기본 모드로 동작 중입니다. 질문은 정상적으로 접수되었습니다. API Key를 강제로 요구하지 않으며, 연결 가능한 무료 Provider가 있으면 우선 사용하고 설정된 Provider가 없을 때는 이 기본 모드가 유지됩니다.\n\n질문: $q';}
Future<void> send()async{final t=controller.text.trim();if((t.isEmpty&&attachment==null)||busy)return;final a=attachment;setState((){messages.add(ChatMessage(t.isEmpty?'첨부 이미지 분석':t,true,attachment:a));controller.clear();attachment=null;busy=true;});try{final k=await secureStorage.read(key:'gemini_api_key')??'';String ans;if(k.isNotEmpty){try{ans=await gemini.chat(apiKey:k,prompt:a==null?t:'$t\n\n첨부 이미지가 선택됨: $a');}catch(_){ans='Gemini 연결에 실패해 기본 모드로 전환했습니다.\n\n${localFallback(t)}';}}else{ans=localFallback(t);}if(mounted)setState(()=>messages.add(ChatMessage(ans,false)));}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>Column(children:[const ListTile(title:Text('AI OS',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),subtitle:Text('최상의 결과를 위한 AI 운영체제')),const Divider(height:1),Expanded(child:messages.isEmpty?const Center(child:Text('무엇을 도와드릴까요?\nAPI 없이도 채팅을 시작할 수 있습니다.',textAlign:TextAlign.center)):ListView.builder(padding:const EdgeInsets.all(8),itemCount:messages.length,itemBuilder:(_,i){final m=messages[i];return Align(alignment:m.user?Alignment.centerRight:Alignment.centerLeft,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Text(m.text))));})),if(busy)const LinearProgressIndicator(),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[IconButton(onPressed:busy?null:attach,icon:const Icon(Icons.add)),Expanded(child:TextField(controller:controller,minLines:1,maxLines:5,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'메시지를 입력하세요...',border:OutlineInputBorder()))),IconButton(onPressed:busy?null:send,icon:const Icon(Icons.send))])))]);}
class AiRoomPage extends StatelessWidget{const AiRoomPage({super.key});@override Widget build(BuildContext c)=>const EmptyPage(title:'AI 대화방',message:'메인 채팅 주제와 연결된 Agent / Provider 처리 과정을 표시합니다.',icon:Icons.hub);}
class HistoryPage extends StatelessWidget{const HistoryPage({super.key});@override Widget build(BuildContext c)=>const EmptyPage(title:'기록',message:'대화 및 최종 결과 기록',icon:Icons.history);}
class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_SettingsPageState();}
class _SettingsPageState extends State<SettingsPage>{bool freeFirst=true,paid=false;final providers=<String,bool>{'기본 모드 (API 불필요)':true,'Gemini':true,'Groq':false,'OpenRouter Free':false,'Hugging Face':false,'OpenAI API':false,'Claude API':false};Future<void> keyDialog(String p)async{if(p.startsWith('기본'))return;final key=p=='Gemini'?'gemini_api_key':'${p.toLowerCase().replaceAll(' ','_')}_api_key';final x=TextEditingController(text:await secureStorage.read(key:key)??'');if(!mounted)return;await showDialog<void>(context:context,builder:(d)=>AlertDialog(title:Text('$p API 설정'),content:TextField(controller:x,obscureText:true,decoration:const InputDecoration(labelText:'API Key (선택사항)')),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('취소')),FilledButton(onPressed:()async{await secureStorage.write(key:key,value:x.text.trim());if(d.mounted)Navigator.pop(d);},child:const Text('저장'))]));}@override Widget build(BuildContext c)=>ListView(children:[const ListTile(title:Text('설정',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold)),subtitle:Text('AI 선택 · API · 비용 · 저장공간')),SwitchListTile(value:freeFirst,onChanged:(v)=>setState(()=>freeFirst=v),title:const Text('무료 AI 우선'),subtitle:const Text('API가 없어도 기본 모드로 채팅 가능')),SwitchListTile(value:paid,onChanged:(v)=>setState(()=>paid=v),title:const Text('유료 API 사용 허용'),subtitle:const Text('기본 OFF')),const Divider(),...providers.entries.map((e)=>Card(child:Column(children:[SwitchListTile(value:e.value,onChanged:e.key.startsWith('기본')?null:(v)=>setState(()=>providers[e.key]=v),title:Text(e.key),subtitle:Text(e.key.startsWith('기본')?'항상 사용 가능':(e.key.contains('API')?'유료 · 선택':'무료 범위 또는 사용자 API · 선택'))),if(!e.key.startsWith('기본'))TextButton.icon(onPressed:()=>keyDialog(e.key),icon:const Icon(Icons.key),label:const Text('API 설정'))]))),const Divider(),const ListTile(title:Text('AI OS'),subtitle:Text('Version 0.2.1\nCreator: Daehyun Kang'))]);}
class EmptyPage extends StatelessWidget{const EmptyPage({required this.title,required this.message,required this.icon,super.key});final String title,message;final IconData icon;@override Widget build(BuildContext c)=>Column(children:[ListTile(title:Text(title,style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold))),Expanded(child:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:52),const SizedBox(height:16),Text(message,textAlign:TextAlign.center)]))))]);}
